/* What a website's every request asks before it can be routed, in one round trip (live site speed, Oct 21). proxy.ts asks of a name, on every page of a website the server has not seen in the last half minute: its creator (profiles, then creators), its published install and whether that theme was imported (store_theme_installs with its settings), its languages and markets (store_localization, then store_settings), and on a subdomain whether the website has a domain of its own (custom_domains): five or six reads, four of them one after another, before a page held at the edge could be sent. `site_route_facts(name)` answers all of them at once, as jsonb: creator_id, published, compat, localization (its default language, languages, markets and visitor language, or null), store (default_country and currency), website_domain (the primary active website domain and its ssl_status, or null). It reads optional tables and columns through to_jsonb and to_regclass, so a database without parts 22, 136 or 173 answers as the separate reads would. Read only, server only: SECURITY DEFINER, executable by service_role alone. Until it runs, the proxy reads the rows one by one as before. Safe to run again. */
CREATE OR REPLACE FUNCTION public.site_route_facts(p_name text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$ DECLARE v_name text := lower(coalesce(p_name, '')); v_creator uuid; v_install uuid; v_kind text; v_loc jsonb; v_store jsonb; v_domain jsonb; BEGIN IF v_name = '' THEN RETURN jsonb_build_object('creator_id', NULL, 'published', false, 'compat', false); END IF; SELECT c.id INTO v_creator FROM public.profiles p JOIN public.creators c ON c.user_id = p.id WHERE p.username = v_name LIMIT 1; IF v_creator IS NULL THEN SELECT c.id INTO v_creator FROM public.creators c WHERE c.slug = v_name LIMIT 1; END IF; IF v_creator IS NULL THEN RETURN jsonb_build_object('creator_id', NULL, 'published', false, 'compat', false); END IF; SELECT i.id, s.settings -> 'compat' ->> 'kind' INTO v_install, v_kind FROM public.store_theme_installs i LEFT JOIN public.store_theme_settings s ON s.install_id = i.id WHERE i.creator_id = v_creator AND i.status = 'published' ORDER BY i.sort_order ASC LIMIT 1; IF to_regclass('public.store_localization') IS NOT NULL THEN EXECUTE 'SELECT jsonb_build_object(''default_language'', j -> ''default_language'', ''languages'', j -> ''languages'', ''markets'', j -> ''markets'', ''visitor_language'', j -> ''visitor_language'') FROM (SELECT to_jsonb(l) AS j FROM public.store_localization l WHERE l.creator_id = $1 LIMIT 1) x' INTO v_loc USING v_creator; END IF; IF to_regclass('public.store_settings') IS NOT NULL THEN EXECUTE 'SELECT jsonb_build_object(''default_country'', to_jsonb(s) -> ''default_country'', ''currency'', to_jsonb(s) -> ''currency'') FROM public.store_settings s WHERE s.creator_id = $1 LIMIT 1' INTO v_store USING v_creator; END IF; IF v_install IS NOT NULL AND to_regclass('public.custom_domains') IS NOT NULL THEN EXECUTE 'SELECT jsonb_build_object(''domain'', d.domain, ''ssl_status'', to_jsonb(d) ->> ''ssl_status'') FROM public.custom_domains d WHERE d.creator_id = $1 AND d.status = ''active'' AND to_jsonb(d) ->> ''purpose'' = ''website'' AND (to_jsonb(d) ->> ''is_primary'') = ''true'' LIMIT 1' INTO v_domain USING v_creator; END IF; RETURN jsonb_build_object('creator_id', v_creator, 'published', v_install IS NOT NULL, 'compat', coalesce(v_kind = 'shopify', false), 'localization', v_loc, 'store', v_store, 'website_domain', v_domain); END $f$;
REVOKE ALL ON FUNCTION public.site_route_facts(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.site_route_facts(text) TO service_role;
notify pgrst, 'reload schema';
